$(document).ready(function () {
    // Basic zero configuration
    $(".zero-configuration").DataTable();

    // Default ordering on column 4 descending
    $(".default-ordering").DataTable({
        order: [[3, "desc"]]
    });

    // Multi-column ordering
    $(".multi-ordering").DataTable({
        columnDefs: [
            {
                targets: [0],
                orderData: [0, 1]
            },
            {
                targets: [1],
                orderData: [1, 0]
            },
            {
                targets: [4],
                orderData: [4, 0]
            }
        ]
    });

    // Complex headers example
    $(".complex-headers").DataTable();

    // DOM positioning
    $(".dom-positioning").DataTable({
        dom: '<"top"i>rt<"bottom"flp><"clear">'
    });

    // Alternative pagination type
    $(".alt-pagination").DataTable({
        pagingType: "full_numbers"
    });

    // Vertical scroll with no paging
    $(".scroll-vertical").DataTable({
        scrollY: "200px",
        scrollCollapse: true,
        paging: false
    });

    // Dynamic height scroll with no paging
    $(".dynamic-height").DataTable({
        scrollY: "50vh",
        scrollCollapse: true,
        paging: false
    });

    // Horizontal scroll only
    $(".scroll-horizontal").DataTable({
        scrollX: true
    });

    // Horizontal and vertical scroll
    $(".scroll-horizontal-vertical").DataTable({
        scrollY: 200,
        scrollX: true
    });

    // Custom comma/decimal format
    $(".comma-decimal-place").DataTable({
        language: {
            decimal: ",",
            thousands: "."
        }
    });
});
